fn load_ai_studio_preferences(path: &std::path::Path) -> AiStudioPreferences {
    let Ok(bytes) = fs::read(path) else {
        return AiStudioPreferences::default();
    };
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
        return AiStudioPreferences::default();
    };
    let model_backend_was_explicit = value.get("model_backend").is_some();
    let Ok(mut preferences) = serde_json::from_value::<AiStudioPreferences>(value) else {
        return AiStudioPreferences::default();
    };
    if preferences.schema_version != AI_STUDIO_PREFERENCES_SCHEMA_VERSION {
        return AiStudioPreferences::default();
    }
    if !model_backend_was_explicit {
        // Schema-v1 preferences written before managed Local AI represented the external
        // Ollama-compatible path even when the default endpoint/model fields were empty.
        preferences.model_backend = ModelBackendPreference::OllamaCompatible;
    }
    preferences
}
